{
  "sop_id": "SOP-017",
  "title": "Vendor Onboarding and Due Diligence",
  "steps": [
    {
      "step_id": "S1",
      "name": "Create ticket and assign",
      "role": "Executor",
      "type": "intake"
    },
    {
      "step_id": "S2",
      "name": "Collect registration form and statutory documents",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S3",
      "name": "Verify PAN, GSTIN and MSME status",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S4",
      "name": "Request bank account validation",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S5",
      "name": "Request sanctions, blacklist and conflict-of-interest screening",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S6",
      "name": "Assess capability and quality",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S7",
      "name": "Assign risk category",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S8",
      "name": "Check payment terms, NDA and code-of-conduct acknowledgement",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "S9",
      "name": "Draft vendor master record and submit",
      "role": "Executor",
      "type": "work"
    },
    {
      "step_id": "DependencyWait",
      "name": "Wait for bank validation (D1) and screening clearance (D2) in parallel",
      "role": "System",
      "type": "intake"
    },
    {
      "step_id": "D1",
      "name": "Bank validation",
      "role": "System",
      "type": "approval"
    },
    {
      "step_id": "D2",
      "name": "Screening clearance",
      "role": "System",
      "type": "approval"
    },
    {
      "step_id": "A1",
      "name": "Incharge review",
      "role": "Incharge",
      "type": "approval"
    },
    {
      "step_id": "A2",
      "name": "Lead approval",
      "role": "Lead",
      "type": "approval"
    },
    {
      "step_id": "A3",
      "name": "HOD approval and activation",
      "role": "HOD",
      "type": "approval"
    },
    {
      "step_id": "R1",
      "name": "Rework on rejection",
      "role": "Executor",
      "type": "rework"
    }
  ],
  "approvals": [
    {
      "stage": "Incharge",
      "condition": "always"
    },
    {
      "stage": "Lead",
      "condition": "always"
    },
    {
      "stage": "HOD",
      "condition": "always"
    }
  ],
  "dependencies": [
    {
      "dep_id": "D1",
      "provider": "Finance",
      "item": "bank account validation",
      "parallel_group": "P1"
    },
    {
      "dep_id": "D2",
      "provider": "Legal/Compliance",
      "item": "sanctions, blacklist and conflict-of-interest screening",
      "parallel_group": "P1"
    }
  ],
  "rework_reasons": [
    "Required document missing",
    "Incorrect category",
    "Amount mismatch",
    "Wrong quantity"
  ],
  "first_pass_yield_target": 0.85
}
